class Solution {
  private static final long MOD = 1_000_000_007L;

  public int numberOfWays(String s, String t, long k) {
    int n = s.length();
    // shifts d (0 <= d < n) that turn s into t
    String text = s + s;
    int matchesAtZero = 0, matchesNonZero = 0;
    int[] z = zFunction(t + "#" + text.substring(0, 2 * n - 1));
    for (int d = 0; d < n; d++) {
      if (z[n + 1 + d] >= n) {
        if (d == 0) matchesAtZero = 1;
        else matchesNonZero++;
      }
    }
    // after m rotations: zero[m] ways to be at shift 0, other[m] ways to be at one given non-zero
    // shift
    long[][] matrix = {{0, n - 1}, {1, n - 2}};
    long[][] p = matrixPower(matrix, k);
    long zero = p[0][0], other = p[1][0]; // start at shift 0
    long answer = (matchesAtZero * zero + matchesNonZero * other) % MOD;
    return (int) answer;
  }

  private int[] zFunction(String s) {
    int n = s.length();
    int[] z = new int[n];
    for (int i = 1, l = 0, r = 0; i < n; i++) {
      if (i < r) z[i] = Math.min(r - i, z[i - l]);
      while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
      if (i + z[i] > r) {
        l = i;
        r = i + z[i];
      }
    }
    return z;
  }

  private long[][] matrixPower(long[][] m, long exp) {
    long[][] result = {{1, 0}, {0, 1}};
    while (exp > 0) {
      if ((exp & 1) == 1) result = multiply(result, m);
      m = multiply(m, m);
      exp >>= 1;
    }
    return result;
  }

  private long[][] multiply(long[][] a, long[][] b) {
    long[][] c = new long[2][2];
    for (int i = 0; i < 2; i++) {
      for (int j = 0; j < 2; j++) {
        for (int k = 0; k < 2; k++) c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD;
      }
    }
    return c;
  }
}
